// One-time catalogue seed for the Admin App (Build 38).
//
// The Phase 1 migration + SQL seeds (hidden_files/link-admin-student/)
// could not be run: the Supabase dashboard browser session is dead and
// the anon key cannot INSERT (RLS is select-only for anon). This seed
// uploads the same bundled catalogue using the signed-in admin's own
// session instead, so one tap on «ډېټا پورته کړه» puts the data in.
//
// Data: bundled JSON assets under assets/seed/ (generated by
// generate_seed_json.py from the SAME verified sources as the SQL
// seeds — catalogue_parsed.json == shipped catalogue.dart):
//   subjects 1,230 · books 227 · book_subjects 670 ·
//   book_placements 616 · reading_books 22.
//
// SAFETY — insert-only-missing (same semantics as the SQL seeds'
// `ON CONFLICT DO NOTHING`):
//   * Nothing is ever overwritten: a second run finds every row
//     already there and inserts 0 rows. Admin edits are never clobbered.
//   * No upsert is used on purpose: `books.app_id` /
//     `reading_books.app_id` have PARTIAL unique indexes (migration.sql),
//     and Postgres cannot infer a partial index for
//     `ON CONFLICT (app_id)` — that upsert would fail with 42P10.
//     Insert-only-missing avoids the problem entirely.
//   * PostgREST returns at most 1,000 rows per request, so every
//     "already there?" check is paginated with .range().
//   * The button refuses to run until the migration has created the
//     tables/columns (see SeedNotReadyError) — it never crashes on a
//     missing table and never attempts DDL.

import 'dart:convert';
import 'dart:io';

import 'package:flutter/services.dart' show rootBundle;
import 'package:http/http.dart' show ClientException;
import 'package:supabase_flutter/supabase_flutter.dart';

import 'supabase_service.dart';

/// Thrown when the Phase 1 migration has not run yet: a table or a
/// column the seed needs does not exist. The screen shows a clear
/// Pashto message instead of crashing.
class SeedNotReadyError implements Exception {
  const SeedNotReadyError();
  @override
  String toString() =>
      'جدولونه لا نه دي جوړ شوي — لومړی migration چلوئ';
}

/// Thrown when the phone has no working internet connection.
class SeedNoInternetError implements Exception {
  const SeedNoInternetError();
  @override
  String toString() =>
      'انټرنېټ نشته — وګورئ چې انټرنېټ وصل دی او بیا هڅه وکړئ';
}

/// Thrown when the signed-in admin may not write (session expired or
/// the admin row is missing / inactive).
class SeedNotAllowedError implements Exception {
  const SeedNotAllowedError();
  @override
  String toString() =>
      'لاسرسی نشته — بیا ننوتل وکړئ او ډاډ ترلاسه کړئ چې ستاسو اکاونټ اډمین دی';
}

/// What the seed did, shown on screen after it finishes.
class SeedResult {
  /// Rows the bundled catalogue expects, per table.
  final Map<String, int> expected;

  /// Rows actually inserted by this run, per table.
  final Map<String, int> inserted;

  /// Rows found in the tables afterwards (verified by counting).
  final Map<String, int> actual;

  /// Rows skipped because a link pointed at a book/subject that was
  /// not found (should always be 0).
  final int skippedLinks;

  const SeedResult({
    required this.expected,
    required this.inserted,
    required this.actual,
    required this.skippedLinks,
  });

  /// True when every table holds exactly the expected number of rows.
  bool get verified => expected.keys.every(
        (k) => actual[k] == expected[k],
      );
}

/// One call per phase, for the progress display.
typedef SeedProgress = void Function(String phase, int done, int total);

class SeedService {
  static const _batchSize = 100;
  static const _pageSize = 1000;

  static const _expectedTables = [
    'subjects',
    'books',
    'book_subjects',
    'book_placements',
    'reading_books',
  ];

  /// Runs the whole seed. Safe to run twice: the second run inserts 0.
  /// Throws [SeedNotReadyError], [SeedNoInternetError] or
  /// [SeedNotAllowedError] (see the classes above).
  static Future<SeedResult> runSeed({
    required SeedProgress onProgress,
  }) async {
    try {
      return await _run(onProgress);
    } on SeedNotReadyError {
      rethrow;
    } on SeedNoInternetError {
      rethrow;
    } on SeedNotAllowedError {
      rethrow;
    } on SocketException {
      throw const SeedNoInternetError();
    } on HttpException {
      throw const SeedNoInternetError();
    } on ClientException {
      throw const SeedNoInternetError();
    } on PostgrestException catch (e) {
      throw _mapPostgrestError(e);
    }
  }

  static Exception _mapPostgrestError(PostgrestException e) {
    if (_isMissingTableOrColumn(e)) return const SeedNotReadyError();
    if (e.code == '42501' ||
        e.code == '401' ||
        e.code == '403' ||
        e.code == 'PGRST301' || // JWT expired
        e.code == 'PGRST302') {
      // JWT invalid
      return const SeedNotAllowedError();
    }
    return e;
  }

  static bool _isMissingTableOrColumn(Object e) =>
      e is PostgrestException &&
      (e.code == '42P01' ||
          e.code == '42703' ||
          e.message.contains('does not exist') ||
          e.message.contains('Could not find the table') ||
          e.message.contains('Could not find the column'));

  static Future<SeedResult> _run(SeedProgress onProgress) async {
    // -------------------------------------------------- 1. load assets
    onProgress('ډېټا لوستل کېږي…', 0, 1);
    final meta = jsonDecode(
      await rootBundle.loadString('assets/seed/seed_meta.json'),
    ) as Map<String, dynamic>;
    final expected = {
      for (final t in _expectedTables) t: (meta[t] as num).toInt(),
    };
    Future<List<Map<String, dynamic>>> load(String name) async {
      final raw = jsonDecode(
        await rootBundle.loadString('assets/seed/$name'),
      ) as List;
      final rows = raw.cast<Map<String, dynamic>>();
      final table = name.replaceAll('.json', '');
      if (rows.length != expected[table]) {
        throw Exception(
          'د $name فایل نیمګړی دی: ${rows.length} کرښې، تمه ${expected[table]} وه.',
        );
      }
      return rows;
    }

    final subjectsJson = await load('subjects.json');
    final booksJson = await load('books.json');
    final linksJson = await load('book_subjects.json');
    final placementsJson = await load('book_placements.json');
    final readingJson = await load('reading_books.json');

    final client = SupabaseService.client;

    // --------------------------------------- 2. departments (code -> id)
    // The migration backfills departments.code (21 rows). If the codes
    // are missing, the migration has not run — refuse, do not guess.
    onProgress('څانګې لوستل کېږي…', 0, 1);
    final departments = await SupabaseService.fetchAllDepartments();
    final deptIdByCode = <String, String>{};
    for (final d in departments) {
      if (d.code.isNotEmpty) deptIdByCode[d.code] = d.id;
    }
    if (deptIdByCode.length < 21) {
      throw const SeedNotReadyError();
    }

    // --------------------------------------------- 3. probe the tables
    // A missing table/column here means the migration has not run.
    // (fetchSubjects already throws SubjectsNotReadyError for this.)
    try {
      await client.from('subjects').select('id').limit(1);
      await client.from('books').select('id,app_id').limit(1);
      await client.from('book_subjects').select('book_id').limit(1);
      await client.from('book_placements').select('book_id').limit(1);
      await client.from('reading_books').select('id,app_id').limit(1);
    } on PostgrestException catch (e) {
      if (_isMissingTableOrColumn(e)) throw const SeedNotReadyError();
      rethrow;
    }

    final inserted = <String, int>{
      for (final t in _expectedTables) t: 0,
    };
    var skippedLinks = 0;

    // ------------------------------------------------- 4. subjects
    // Key = (department_id, semester_number, name, code), the same
    // unique key the SQL seed uses.
    final subjectIdByKey = <String, String>{};
    final existingSubjects = await _selectAll(
      'subjects',
      'id,department_id,semester_number,name,code',
    );
    for (final r in existingSubjects) {
      subjectIdByKey[_subjectKey(r)] = r['id'] as String;
    }
    final subjectsToInsert = <Map<String, dynamic>>[];
    for (final s in subjectsJson) {
      final deptId = deptIdByCode[s['department'] as String];
      if (deptId == null) {
        skippedLinks++;
        continue;
      }
      final row = {
        'department_id': deptId,
        'semester_number': s['semester'],
        'name': s['name'],
        'code': s['code'],
        'credits': s['credits'],
        'sort_order': s['sort_order'],
        'is_active': true,
      };
      if (!subjectIdByKey.containsKey(_subjectKey(row))) {
        subjectsToInsert.add(row);
      }
    }
    inserted['subjects'] = await _insertBatches(
      table: 'subjects',
      rows: subjectsToInsert,
      returning: 'id,department_id,semester_number,name,code',
      onProgress: (done) => onProgress(
        'مضمونونه پورته کېږي…',
        done,
        subjectsToInsert.length,
      ),
      onInserted: (r) => subjectIdByKey[_subjectKey(r)] = r['id'] as String,
    );

    // ---------------------------------------------------- 5. books
    final bookIdByAppId = <String, String>{};
    final existingBooks = await _selectAll('books', 'id,app_id');
    for (final r in existingBooks) {
      final appId = r['app_id'] as String?;
      if (appId != null && appId.isNotEmpty) {
        bookIdByAppId[appId] = r['id'] as String;
      }
    }
    final booksToInsert = <Map<String, dynamic>>[];
    for (final b in booksJson) {
      final appId = b['app_id'] as String;
      if (bookIdByAppId.containsKey(appId)) continue;
      final deptCode = b['department'] as String?;
      booksToInsert.add({
        'app_id': appId,
        'department_id':
            deptCode == null ? null : deptIdByCode[deptCode],
        'semester_number': b['semester'],
        'title': b['title'],
        'title_ps': b['title_ps'],
        'subject': b['subject'],
        'author': b['author'],
        'cover_url': null,
        'pdf_url': b['pdf_url'],
        'file_size_bytes': 0,
        'edition': null,
        'year': null,
        'is_archived': false,
        'download_count': 0,
      });
    }
    inserted['books'] = await _insertBatches(
      table: 'books',
      rows: booksToInsert,
      returning: 'id,app_id',
      onProgress: (done) => onProgress(
        'کتابونه پورته کېږي…',
        done,
        booksToInsert.length,
      ),
      onInserted: (r) {
        final appId = r['app_id'] as String?;
        if (appId != null) bookIdByAppId[appId] = r['id'] as String;
      },
    );

    // --------------------------------------------- 6. book_subjects
    final existingLinks = await _selectAll(
      'book_subjects',
      'book_id,subject_id',
    );
    final existingLinkKeys = {
      for (final r in existingLinks)
        '${r['book_id']}|${r['subject_id']}',
    };
    final linksToInsert = <Map<String, dynamic>>[];
    for (final l in linksJson) {
      final bookId = bookIdByAppId[l['book'] as String];
      final subjectId = subjectIdByKey[_subjectKey({
        'department_id': deptIdByCode[l['department'] as String],
        'semester_number': l['semester'],
        'name': l['subject'],
        'code': l['code'],
      })];
      if (bookId == null || subjectId == null) {
        skippedLinks++;
        continue;
      }
      if (existingLinkKeys.contains('$bookId|$subjectId')) continue;
      linksToInsert.add({'book_id': bookId, 'subject_id': subjectId});
    }
    inserted['book_subjects'] = await _insertBatches(
      table: 'book_subjects',
      rows: linksToInsert,
      returning: 'book_id',
      onProgress: (done) => onProgress(
        'د کتابونو تړنې پورته کېږي…',
        done,
        linksToInsert.length,
      ),
    );

    // -------------------------------------------- 7. book_placements
    final existingPlacements = await _selectAll(
      'book_placements',
      'book_id,department_id,semester_number',
    );
    final existingPlacementKeys = {
      for (final r in existingPlacements)
        '${r['book_id']}|${r['department_id']}|${r['semester_number']}',
    };
    final placementsToInsert = <Map<String, dynamic>>[];
    for (final p in placementsJson) {
      final bookId = bookIdByAppId[p['book'] as String];
      final deptId = deptIdByCode[p['department'] as String];
      if (bookId == null || deptId == null) {
        skippedLinks++;
        continue;
      }
      final key = '$bookId|$deptId|${p['semester']}';
      if (existingPlacementKeys.contains(key)) continue;
      placementsToInsert.add({
        'book_id': bookId,
        'department_id': deptId,
        'semester_number': p['semester'],
      });
    }
    inserted['book_placements'] = await _insertBatches(
      table: 'book_placements',
      rows: placementsToInsert,
      returning: 'book_id',
      onProgress: (done) => onProgress(
        'د کتابونو ځایونه پورته کېږي…',
        done,
        placementsToInsert.length,
      ),
    );

    // --------------------------------------------- 8. reading books
    final existingReading = await _selectAll('reading_books', 'id,app_id');
    final existingReadingAppIds = {
      for (final r in existingReading)
        if ((r['app_id'] as String?)?.isNotEmpty ?? false)
          r['app_id'] as String,
    };
    final readingToInsert = <Map<String, dynamic>>[];
    for (final b in readingJson) {
      final appId = b['app_id'] as String;
      if (existingReadingAppIds.contains(appId)) continue;
      readingToInsert.add({
        'app_id': appId,
        'category': b['category'],
        'title': b['title'],
        'title_ps': b['title_ps'],
        'author': b['author'],
        'cover_url': null,
        'pdf_url': b['pdf_url'],
        'has_permission': false,
        'is_archived': false,
        'year': null,
      });
    }
    inserted['reading_books'] = await _insertBatches(
      table: 'reading_books',
      rows: readingToInsert,
      returning: 'id',
      onProgress: (done) => onProgress(
        'د مطالعې کتابونه پورته کېږي…',
        done,
        readingToInsert.length,
      ),
    );

    // ------------------------------------------- 9. verify by counting
    // NOTE (2026-11-27): book_subjects / book_placements have NO `id`
    // column — their key is the composite (book_id, subject_id) /
    // (book_id, department_id, semester_number). Counting every table
    // by `id` made this step throw SeedNotReadyError AFTER a fully
    // successful upload (all 1,230 + 227 + 670 + 616 + 22 rows were in
    // the database), so count the two link tables by `book_id`.
    onProgress('تایید کېږي…', 0, 1);
    final actual = <String, int>{};
    for (final t in _expectedTables) {
      final countColumn =
          (t == 'book_subjects' || t == 'book_placements')
              ? 'book_id'
              : 'id';
      actual[t] = (await _selectAll(t, countColumn)).length;
    }

    // One audit entry for the whole seed (never breaks the result).
    await SupabaseService.logSeed(
      inserted: inserted.values.fold(0, (a, b) => a + b),
      verified: _expectedTables.every((t) => actual[t] == expected[t]),
    );

    return SeedResult(
      expected: expected,
      inserted: inserted,
      actual: actual,
      skippedLinks: skippedLinks,
    );
  }

  static String _subjectKey(Map<String, dynamic> r) =>
      '${r['department_id']}|${r['semester_number']}|${r['name']}|${r['code']}';

  /// All rows of a table, paginated (PostgREST returns at most 1,000
  /// rows per request).
  static Future<List<Map<String, dynamic>>> _selectAll(
    String table,
    String columns,
  ) async {
    final out = <Map<String, dynamic>>[];
    var from = 0;
    while (true) {
      final rows = await SupabaseService.client
          .from(table)
          .select(columns)
          .range(from, from + _pageSize - 1);
      final list = (rows as List).cast<Map<String, dynamic>>();
      out.addAll(list);
      if (list.length < _pageSize) break;
      from += _pageSize;
    }
    return out;
  }

  /// Inserts [rows] in batches of [_batchSize]. Returns how many rows
  /// were inserted. [returning] is always selected back (the insert
  /// response carries the generated uuids); each inserted row is
  /// reported to [onInserted] when given.
  static Future<int> _insertBatches({
    required String table,
    required List<Map<String, dynamic>> rows,
    required String returning,
    required void Function(int done) onProgress,
    void Function(Map<String, dynamic> row)? onInserted,
  }) async {
    var done = 0;
    for (var i = 0; i < rows.length; i += _batchSize) {
      final batch = rows.sublist(
        i,
        (i + _batchSize).clamp(0, rows.length),
      );
      final inserted = await SupabaseService.client
          .from(table)
          .insert(batch)
          .select(returning);
      if (onInserted != null) {
        for (final r in (inserted as List).cast<Map<String, dynamic>>()) {
          onInserted(r);
        }
      }
      done += batch.length;
      onProgress(done);
    }
    onProgress(rows.length);
    return rows.length;
  }
}
